INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('4a6745cd-acc6-5a1d-9ed3-a7bd6fae37ba', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 1, 1, 'What is meant by the acceleration of an object?', NULL, 1, 'multiple_choice'::answer_type, 'The rate of change of velocity', NULL, false, NULL, false, NULL, 'a = Δv/Δt, the change in velocity per unit time. Mark scheme (1 mark). B1: C (The rate of change of velocity).', 1, NULL, NULL),
('b3e695a4-b394-599a-8193-03c9b744ca80', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 2, 2, 'Is acceleration a scalar or a vector quantity?', NULL, 1, 'multiple_choice'::answer_type, 'A vector, because velocity is a vector', NULL, false, NULL, false, NULL, 'Acceleration has the direction of Δv. Mark scheme (1 mark). B1: A (A vector, because velocity is a vector).', 1, NULL, NULL),
('2b41c6b5-f22a-5f99-9beb-28bec2f30acf', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 3, 3, 'A car speeds up from rest to 18 m s⁻¹ in 6.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '3', 'm s⁻²', false, NULL, false, NULL, 'a = (18 − 0) ÷ 6.0 = 3.0 m s⁻². Mark scheme (2 marks). C1: a = Δv/t. A1: a = 3.0 m s⁻².', 2, NULL, NULL),
('39594658-80f1-5438-9a5f-a86f00b9b796', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 4, 4, 'A car has an acceleration of 2 m s⁻². What does this mean?', NULL, 1, 'multiple_choice'::answer_type, 'Its velocity increases by 2 m s⁻¹ every second', NULL, false, NULL, false, NULL, 'Acceleration is the change of velocity per second. Mark scheme (1 mark). B1: D (Its velocity increases by 2 m s⁻¹ every second).', 1, NULL, NULL),
('156e1eff-b6cf-541e-93eb-a80864feee3b', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 5, 5, 'What is meant by a deceleration?', NULL, 1, 'multiple_choice'::answer_type, 'An acceleration that reduces the speed', NULL, false, NULL, false, NULL, 'The acceleration is opposite to the velocity. Mark scheme (1 mark). B1: B (An acceleration that reduces the speed).', 1, NULL, NULL),
('2627962f-1f0b-5ed6-8580-e914d0844b25', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 6, 6, 'A cyclist slows from 8.0 m s⁻¹ to 2.0 m s⁻¹ in 3.0 s. Calculate her acceleration.', NULL, 1, 'numeric'::answer_type, '-2', 'm s⁻²', false, NULL, true, NULL, 'a = (2.0 − 8.0) ÷ 3.0 = −2.0 m s⁻². Mark scheme (2 marks). C1: negative for slowing. A1: a = −2.0 m s⁻².', 2, NULL, NULL),
('0f4050ce-fd72-52e4-9b5f-0271cd27736a', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 7, 7, 'A car moves at a constant 25 m s⁻¹ along a straight road. What is its acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'The velocity does not change. Mark scheme (1 mark). B1: C (Zero).', 1, NULL, NULL),
('4bac4019-7add-5fb7-a005-5bfa5e28e3da', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 8, 8, 'Can an object accelerate while its speed stays constant?', NULL, 1, 'multiple_choice'::answer_type, 'Yes, if its direction changes', NULL, false, NULL, false, NULL, 'For example uniform circular motion. Mark scheme (1 mark). B1: A (Yes, if its direction changes).', 1, NULL, NULL),
('fbc27874-853f-5eb3-bd67-4a3f2d12588b', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 9, 9, 'A ball rolls down a slope, its velocity rising by 0.60 m s⁻¹ every second. State its acceleration.', NULL, 1, 'numeric'::answer_type, '0.6', 'm s⁻²', false, NULL, false, NULL, 'a = 0.60 ÷ 1.0 = 0.60 m s⁻². Mark scheme (2 marks). C1: change per second. A1: a = 0.60 m s⁻².', 2, NULL, NULL),
('8fcabf26-91a8-56fb-bc5a-6bc34a2ab9c2', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 10, 10, 'A ball is thrown straight up. Taking up as positive, what is the sign of its acceleration while it rises?', NULL, 1, 'multiple_choice'::answer_type, 'Negative', NULL, false, NULL, false, NULL, 'Gravity acts downwards all the time. Mark scheme (1 mark). B1: D (Negative).', 1, NULL, NULL),
('6cdc5198-477c-51f5-9285-0ce1d71c294e', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 11, 11, 'A sprinter reaches 9.0 m s⁻¹ from rest in 2.0 s. Calculate her average acceleration.', NULL, 1, 'numeric'::answer_type, '4.5', 'm s⁻²', false, NULL, false, NULL, 'a = 9.0 ÷ 2.0 = 4.5 m s⁻². Mark scheme (2 marks). C1: a = Δv/t. A1: a = 4.5 m s⁻².', 2, NULL, NULL),
('53443ea8-4815-5168-9269-c54aade0d434', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 12, 12, 'Which of these is accelerating?', NULL, 1, 'multiple_choice'::answer_type, 'A car going round a roundabout at constant speed', NULL, false, NULL, false, NULL, 'Its direction, and so its velocity, is changing. Mark scheme (1 mark). B1: B (A car going round a roundabout at constant speed).', 1, NULL, NULL),
('9d82843b-38e2-53ed-8ce5-387b1d831fb2', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 13, 13, 'A trolley''s velocity increases from 0.20 m s⁻¹ to 0.80 m s⁻¹ in 2.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '0.3', 'm s⁻²', false, NULL, false, NULL, 'a = (0.80 − 0.20) ÷ 2.0 = 0.30 m s⁻². Mark scheme (1 mark). A1: a = 0.30 m s⁻².', 1, NULL, NULL),
('3dc1ef01-77db-5cae-8dcd-47c60e73e08b', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 14, 14, 'A car accelerates at 3 m s⁻² from rest. What is its speed after 4 s?', NULL, 1, 'multiple_choice'::answer_type, '12 m s⁻¹', NULL, false, NULL, false, NULL, 'v = u + at = 0 + 3 × 4 = 12 m s⁻¹. Mark scheme (1 mark). B1: C (12 m s⁻¹).', 1, NULL, NULL),
('eb99f3cb-f057-5524-b2d4-02662fa43fa2', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 15, 15, 'A lorry accelerates at 0.50 m s⁻² for 20 s from 4.0 m s⁻¹. Calculate its final velocity.', NULL, 1, 'numeric'::answer_type, '14', 'm s⁻¹', false, NULL, false, NULL, 'v = 4.0 + 0.50 × 20 = 14 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 14 m s⁻¹.', 2, NULL, NULL),
('1632a791-7503-581c-814e-b5cbad21e0a8', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 16, 16, 'A moving car has a negative velocity and a negative acceleration. What is happening?', NULL, 1, 'multiple_choice'::answer_type, 'It is speeding up in the negative direction', NULL, false, NULL, false, NULL, 'Velocity and acceleration in the same direction mean speeding up. Mark scheme (1 mark). B1: A (It is speeding up in the negative direction).', 1, NULL, NULL),
('efc2ca44-73ae-5b04-866c-ad09175937ff', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 17, 17, 'A boat moving at 6.0 m s⁻¹ decelerates at 0.40 m s⁻². How long does it take to stop?', NULL, 1, 'numeric'::answer_type, '15', 's', false, NULL, false, NULL, 't = 6.0 ÷ 0.40 = 15 s. Mark scheme (2 marks). C1: t = Δv/a. A1: t = 15 s.', 2, NULL, NULL),
('5bac7384-89a4-5570-bab2-f58844b1dea0', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 18, 18, 'A train moving forwards has an acceleration of −0.5 m s⁻². What is happening?', NULL, 1, 'multiple_choice'::answer_type, 'It is slowing down by 0.5 m s⁻¹ every second', NULL, false, NULL, false, NULL, 'The acceleration is opposite to the velocity. Mark scheme (1 mark). B1: A (It is slowing down by 0.5 m s⁻¹ every second).', 1, NULL, NULL),
('b3179baa-d4a6-5230-80dd-9035db102f9d', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 19, 19, 'A skier accelerates from 2.0 m s⁻¹ at 1.5 m s⁻² for 4.0 s. Calculate her final speed.', NULL, 1, 'numeric'::answer_type, '8', 'm s⁻¹', false, NULL, false, NULL, 'v = 2.0 + 1.5 × 4.0 = 8.0 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 8.0 m s⁻¹.', 2, NULL, NULL),
('a7080753-4deb-5288-9037-f353ec4f155d', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 20, 20, 'A horse''s velocity increases by 1.2 m s⁻¹ each second for 5.0 s from rest. Calculate its final velocity.', NULL, 1, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'v = 1.2 × 5.0 = 6.0 m s⁻¹. Mark scheme (1 mark). A1: v = 6.0 m s⁻¹.', 1, NULL, NULL),
('caea58a6-b2e1-5aa0-b34b-cc74db129134', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 21, 21, 'A ball moving up a slope slows down, stops and rolls back. Taking up the slope as positive, which describes its acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Negative and constant throughout', NULL, false, NULL, false, NULL, 'The component of gravity down the slope does not change. Mark scheme (3 marks). C1: direction down slope. C1: constant, including at the top. A1: D (Negative and constant throughout).', 3, NULL, NULL),
('8aaa7c85-f3e5-5cd7-9b3e-04f9441bb772', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 22, 22, 'A jet accelerates from 60 m s⁻¹ to 80 m s⁻¹ at 2.5 m s⁻². How long does this take?', NULL, 2, 'numeric'::answer_type, '8', 's', false, NULL, false, NULL, 't = (80 − 60) ÷ 2.5 = 8.0 s. Mark scheme (3 marks). C1: Δv. C1: t = Δv/a. A1: t = 8.0 s.', 3, NULL, NULL),
('fe7ba032-a58d-59e6-8b32-c6ccacd886e6', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 23, 23, 'A car travelling at 72 km h⁻¹ stops in 4.0 s. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '-5', 'm s⁻²', false, NULL, true, NULL, 'u = 72 ÷ 3.6 = 20 m s⁻¹; a = (0 − 20) ÷ 4.0 = −5.0 m s⁻². Mark scheme (3 marks). C1: km h⁻¹ to m s⁻¹. C1: a with sign. A1: a = −5.0 m s⁻².', 3, NULL, NULL),
('99dc5952-2365-5ad7-ad17-578db43f5a6b', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 24, 24, 'At the highest point of a ball thrown vertically upwards, what are its velocity and acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Velocity zero; acceleration 9.81 m s⁻² downwards', NULL, false, NULL, false, NULL, 'Gravity still acts at the top. Mark scheme (3 marks). C1: v = 0. C1: a = g downwards. A1: B (Velocity zero; acceleration 9.81 m s⁻² downwards).', 3, NULL, NULL),
('4053ce10-5471-5e33-a189-47c50fe4da3d', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 25, 25, 'Taking up as positive, a ball is thrown upwards at 15 m s⁻¹ and is caught moving downwards at 15 m s⁻¹ after 3.06 s. Calculate its average acceleration.', NULL, 2, 'numeric'::answer_type, '-9.804', 'm s⁻²', false, NULL, true, NULL, 'a = (−15 − 15) ÷ 3.06 = −9.80 m s⁻². Mark scheme (3 marks). C1: Δv = −30 m s⁻¹. C1: ÷ time. A1: a = −9.80 m s⁻².', 3, NULL, NULL),
('bc63637b-17e4-5816-9778-6f1f232964f0', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 26, 26, 'A train decelerates uniformly from 30 m s⁻¹ at 0.75 m s⁻². What is its velocity after 24 s?', NULL, 2, 'numeric'::answer_type, '12', 'm s⁻¹', false, NULL, false, NULL, 'v = 30 − 0.75 × 24 = 12 m s⁻¹. Mark scheme (3 marks). C1: v = u + at, a negative. C1: value. A1: v = 12 m s⁻¹.', 3, NULL, NULL),
('bab3ef7f-9551-5fa0-bff0-d9a6fa2d17d4', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 27, 27, 'Car A goes from 0 to 27 m s⁻¹ in 9.0 s; car B from 10 to 30 m s⁻¹ in 5.0 s. Which has the greater acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Car B (4.0 m s⁻² against 3.0 m s⁻²)', NULL, false, NULL, false, NULL, 'Compare Δv/t for each. Mark scheme (3 marks). C1: car A 3.0. C1: car B 4.0. A1: C (Car B (4.0 m s⁻² against 3.0 m s⁻²)).', 3, NULL, NULL),
('4ef4f252-c7f9-542c-85c7-945b756300ef', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 28, 28, 'A rocket accelerates uniformly from rest at 25 m s⁻². How long does it take to reach 1.5 km s⁻¹?', NULL, 2, 'numeric'::answer_type, '60', 's', false, NULL, false, NULL, 't = 1500 ÷ 25 = 60 s. Mark scheme (3 marks). C1: km s⁻¹ to m s⁻¹. C1: t = v/a. A1: t = 60 s.', 3, NULL, NULL),
('bad8c9a2-9dab-53fb-96f0-973cbeb185f6', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 29, 29, 'A lift moving up begins to slow down as it nears the top floor. Taking up as positive, what are the signs of velocity and acceleration?', NULL, 2, 'multiple_choice'::answer_type, 'Velocity positive, acceleration negative', NULL, false, NULL, false, NULL, 'Slowing means a opposes v. Mark scheme (3 marks). C1: v up. C1: a down. A1: A (Velocity positive, acceleration negative).', 3, NULL, NULL),
('e19b166a-ec91-5363-8d43-2e863e739480', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 30, 30, 'A cheetah accelerates from 5.0 m s⁻¹ to 25 m s⁻¹ in 3.2 s. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '6.25', 'm s⁻²', false, NULL, false, NULL, 'a = (25 − 5.0) ÷ 3.2 = 6.25 m s⁻². Mark scheme (3 marks). C1: Δv. C1: ÷ t. A1: a = 6.25 m s⁻².', 3, NULL, NULL),
('bd04dad6-3547-5242-9be7-416d7ccc994c', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 31, 31, 'A parachutist falling at 50 m s⁻¹ opens the parachute and slows to 8.0 m s⁻¹ in 3.0 s. Taking down as positive, calculate the average acceleration.', NULL, 2, 'numeric'::answer_type, '-14', 'm s⁻²', false, NULL, true, NULL, 'a = (8.0 − 50) ÷ 3.0 = −14 m s⁻². Mark scheme (3 marks). C1: Δv negative. C1: value. A1: a = −14 m s⁻².', 3, NULL, NULL),
('8fae8ce2-4994-5716-af6d-9eca1cd7fbdd', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 32, 32, 'Why do we say a car on a circular track at constant speed is accelerating?', NULL, 2, 'multiple_choice'::answer_type, 'Its velocity changes because its direction changes', NULL, false, NULL, false, NULL, 'Acceleration is the rate of change of velocity, a vector. Mark scheme (3 marks). C1: velocity is a vector. C1: direction changes. A1: D (Its velocity changes because its direction changes).', 3, NULL, NULL),
('25b1bc8c-a477-5b40-92f4-ee5686f722b4', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 33, 33, 'A car accelerates at 2.4 m s⁻² for 5.0 s and reaches 22 m s⁻¹. Calculate its initial velocity.', NULL, 2, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, 'u = v − at = 22 − 2.4 × 5.0 = 10 m s⁻¹. Mark scheme (3 marks). C1: rearranged. C1: value. A1: u = 10 m s⁻¹.', 3, NULL, NULL),
('31403f18-610d-5257-9860-5c105f76b805', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 34, 34, 'A tennis ball is hit, changing its velocity from 20 m s⁻¹ towards the racket to 30 m s⁻¹ away in 0.0040 s. Calculate the magnitude of its average acceleration.', NULL, 2, 'numeric'::answer_type, '12500', 'm s⁻²', false, NULL, false, NULL, 'a = (30 + 20) ÷ 0.0040 = 12 500 m s⁻². Mark scheme (3 marks). C1: Δv = 50. C1: ÷ t. A1: a = 1.25 × 10⁴ m s⁻².', 3, NULL, NULL),
('e1ce23b1-41ce-57b4-8e62-81c738f698b4', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 35, 35, 'An object''s velocity changes from +4 m s⁻¹ to −4 m s⁻¹. Which is true?', NULL, 2, 'multiple_choice'::answer_type, 'Its speed is unchanged but it has accelerated', NULL, false, NULL, false, NULL, 'Δv = −8 m s⁻¹ even though the speed is the same. Mark scheme (3 marks). C1: speed same. C1: Δv non-zero. A1: B (Its speed is unchanged but it has accelerated).', 3, NULL, NULL),
('b8928223-fd62-5cea-be93-d73c5e664492', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 36, 36, 'A bus decelerates at 1.5 m s⁻² from 18 m s⁻¹. How long does it take to halve its speed?', NULL, 2, 'numeric'::answer_type, '6', 's', false, NULL, false, NULL, 't = (18 − 9.0) ÷ 1.5 = 6.0 s. Mark scheme (3 marks). C1: Δv = 9.0. C1: t = Δv/a. A1: t = 6.0 s.', 3, NULL, NULL),
('d336a65c-8c62-5cde-a505-604afa315c9f', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 37, 37, 'A runner accelerates uniformly from rest to 8.0 m s⁻¹ in 2.5 s and then decelerates uniformly to rest in 4.0 s. Calculate (magnitude of first acceleration) ÷ (magnitude of deceleration).', NULL, 2, 'numeric'::answer_type, '1.6', NULL, false, NULL, false, NULL, 'a₁ = 8.0 ÷ 2.5 = 3.2 m s⁻²; a₂ = 8.0 ÷ 4.0 = 2.0 m s⁻²; ratio = 3.2 ÷ 2.0 = 1.6. Mark scheme (4 marks). C1: a₁. C1: a₂. C1: ratio. A1: ratio = 1.6.', 4, NULL, NULL),
('aec89598-4a04-5dcd-87aa-1678d0d8c232', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 38, 38, 'A stone is thrown upwards. When does its acceleration change?', NULL, 2, 'multiple_choice'::answer_type, 'Never — it is g downwards throughout (ignoring air resistance)', NULL, false, NULL, false, NULL, 'Only gravity acts on it, so a = g downwards at all times. Mark scheme (3 marks). C1: constant g. C1: direction down. A1: C (Never — it is g downwards throughout (ignoring air resistance)).', 3, NULL, NULL),
('46f125c0-6722-56ab-b2a8-ac434ea90a48', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 39, 39, 'A ball rolling at 4.0 m s⁻¹ across a rough floor stops in 5.0 s. Calculate its average acceleration.', NULL, 2, 'numeric'::answer_type, '-0.8', 'm s⁻²', false, NULL, true, NULL, 'a = (0 − 4.0) ÷ 5.0 = −0.80 m s⁻². Mark scheme (3 marks). C1: Δv negative. C1: value. A1: a = −0.80 m s⁻².', 3, NULL, NULL),
('6601e157-fe44-5ad5-a638-b1321a9d7350', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 40, 40, 'An object''s velocity is zero at one instant. Must its acceleration be zero at that instant?', NULL, 2, 'multiple_choice'::answer_type, 'No; for example a ball at the top of its flight has v = 0 but a = g', NULL, false, NULL, false, NULL, 'Zero velocity does not mean zero rate of change of velocity. Mark scheme (3 marks). C1: no. C1: example. A1: D (No; for example a ball at the top of its flight has v = 0 but a = g).', 3, NULL, NULL),
('20858041-5dd0-5905-ac8c-3ba5aa1b72d1', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 41, 41, 'A car accelerates at 1.6 m s⁻² from 9.0 m s⁻¹. How long does it take to reach 25 m s⁻¹?', NULL, 2, 'numeric'::answer_type, '10', 's', false, NULL, false, NULL, 't = (25 − 9.0) ÷ 1.6 = 10 s. Mark scheme (3 marks). C1: Δv. C1: t = Δv/a. A1: t = 10 s.', 3, NULL, NULL),
('a5e61d79-d6e7-59c3-a2ba-2009bb89642a', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 42, 42, 'A car moving at 12 m s⁻¹ accelerates uniformly at 1.8 m s⁻² for 6.0 s, then decelerates uniformly to rest in 8.0 s. (a) Calculate the maximum speed. (b) Calculate the deceleration.', NULL, 3, 'numeric'::answer_type, '2.85', 'm s⁻²', false, NULL, false, NULL, '(a) v = 12 + 1.8 × 6.0 = 22.8 m s⁻¹. (b) a = 22.8 ÷ 8.0 = 2.85 m s⁻². Mark scheme (5 marks). C1: v = u + at. C1: 22.8 m s⁻¹. M1: a = Δv/t. C1: value. A1: a = 2.85 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg54fe7217-t fg54fe7217-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg54fe7217-t">Speeding up then braking</title><desc id="fg54fe7217-d">A v–t graph rising in a straight line from 12 m s⁻¹ for 6.0 s and then falling in a straight line to zero over 8.0 s.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="200.4" x2="382" y2="200.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="158.8" x2="382" y2="158.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="117.2" x2="382" y2="117.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="75.6" x2="382" y2="75.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="100" y1="242" x2="100" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="100" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="170.5" y1="242" x2="170.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="241" y1="242" x2="241" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="241" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">9</text><line x1="311.5" y1="242" x2="311.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">15</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="200.4" x2="29.4" y2="200.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="200.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="158.8" x2="29.4" y2="158.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="158.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="117.2" x2="29.4" y2="117.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="117.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">15</text><line x1="25.4" y1="75.6" x2="29.4" y2="75.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="75.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">25</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v / m s⁻¹</text><polyline points="29.4,142.2 170.5,52.3 358.5,242" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="37.4" y="156.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">12 m s⁻¹</text></svg>', 'A v–t graph rising in a straight line from 12 m s⁻¹ for 6.0 s and then falling in a straight line to zero over 8.0 s.'),
('4314cbb8-d7f3-5355-bd17-5e461d8d3d87', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 43, 43, 'A ball hits the ground at 9.0 m s⁻¹ and rebounds at 6.0 m s⁻¹; contact lasts 0.025 s. Taking up as positive: (a) state the initial and final velocities with signs; (b) calculate Δv; (c) calculate the average acceleration.', NULL, 3, 'numeric'::answer_type, '600', 'm s⁻²', false, NULL, false, NULL, '(a) u = −9.0 m s⁻¹, v = +6.0 m s⁻¹. (b) Δv = 6.0 − (−9.0) = 15 m s⁻¹. (c) a = 15 ÷ 0.025 = 600 m s⁻². Mark scheme (6 marks). C1: signs. C1: Δv. M1: a = Δv/t. C1: value. B1: direction up. A1: a = 600 m s⁻².', 6, NULL, NULL),
('1af35b89-9c54-542a-b46b-0127fd1fa7de', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 44, 44, 'A satellite moves in a circle at 7.0 km s⁻¹. Its velocity turns through 90° in 1200 s. (a) Calculate |Δv|. (b) Calculate the magnitude of its average acceleration over this time.', NULL, 3, 'numeric'::answer_type, '8.25', 'm s⁻²', false, NULL, false, NULL, '(a) |Δv| = √(7000² + 7000²) = 9899 m s⁻¹. (b) a = 9899 ÷ 1200 = 8.25 m s⁻². Mark scheme (5 marks). M1: vector change. C1: |Δv|. M1: ÷ t. C1: value. A1: a = 8.25 m s⁻².', 5, NULL, NULL),
('a65f2de4-9d04-5283-9a93-3fe1d6a3e0f8', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 45, 45, 'A train has a maximum acceleration of 0.80 m s⁻² and a maximum deceleration of 1.2 m s⁻². Between stations it reaches 24 m s⁻¹. (a) Calculate the time to reach 24 m s⁻¹ from rest. (b) Calculate the time to stop from 24 m s⁻¹. (c) Calculate the shortest total time spent accelerating and braking.', NULL, 3, 'numeric'::answer_type, '50', 's', false, NULL, false, NULL, '(a) t₁ = 24 ÷ 0.80 = 30 s. (b) t₂ = 24 ÷ 1.2 = 20 s. (c) t = 30 + 20 = 50 s. Mark scheme (6 marks). M1: t = Δv/a. C1: t₁. C1: t₂. C1: sum. C1: value. A1: t = 50 s.', 6, NULL, NULL),
('28ca3649-029b-5538-b849-9b0a2073f65d', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 46, 46, 'A sprinter accelerates uniformly from rest at 3.6 m s⁻² until reaching 10.8 m s⁻¹, then runs at constant speed. (a) Calculate the time spent accelerating. (b) State her acceleration after this time.', NULL, 3, 'numeric'::answer_type, '3', 's', false, NULL, false, NULL, '(a) t = 10.8 ÷ 3.6 = 3.0 s. (b) Zero, because her velocity is then constant. Mark scheme (5 marks). M1: t = Δv/a. C1: value. B1: zero. B1: reason. A1: t = 3.0 s.', 5, NULL, NULL),
('ac8fd3db-5604-5b5b-836d-e9b2dfb23947', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 47, 47, 'A lift starts from rest, accelerates upwards at 1.5 m s⁻² for 2.0 s, moves at constant speed and then decelerates at 1.0 m s⁻² to rest. (a) Calculate the maximum speed. (b) Calculate the braking time.', NULL, 3, 'numeric'::answer_type, '3', 's', false, NULL, false, NULL, '(a) v = 1.5 × 2.0 = 3.0 m s⁻¹. (b) t = 3.0 ÷ 1.0 = 3.0 s. Mark scheme (5 marks). C1: v = at. C1: 3.0 m s⁻¹. M1: t = v/a. C1: value. A1: t = 3.0 s.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg05db2dbd-t fg05db2dbd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg05db2dbd-t">Lift journey</title><desc id="fg05db2dbd-d">A lift v–t graph: a straight rise from rest for 2.0 s, constant speed, then a straight fall to rest; the constant-speed time is not to scale.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="95.6" y1="34" x2="95.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="95.6" y1="242" x2="95.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="95.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="190" x2="24" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1</text><line x1="20" y1="138" x2="24" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="86" x2="24" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v / m s⁻¹</text><polyline points="24,242 95.6,86 238.8,86 346.2,242" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A lift v–t graph: a straight rise from rest for 2.0 s, constant speed, then a straight fall to rest; the constant-speed time is not to scale.'),
('4a930da8-87fe-537a-84b0-b76de35ffa4a', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 48, 48, 'A car travels round a bend, its velocity changing from 20 m s⁻¹ north to 20 m s⁻¹ east in 5.0 s. (a) Explain why the car accelerates although its speed is constant. (b) Calculate |Δv|. (c) Calculate the average acceleration.', NULL, 3, 'numeric'::answer_type, '5.657', 'm s⁻²', false, NULL, false, NULL, '(a) Velocity is a vector and its direction changes. (b) |Δv| = √(20² + 20²) = 28.28 m s⁻¹. (c) a = 28.28 ÷ 5.0 = 5.66 m s⁻². Mark scheme (6 marks). B1: direction change. M1: vector subtraction. C1: |Δv|. M1: ÷ t. C1: value. A1: a = 5.66 m s⁻².', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg0696b24b-t fg0696b24b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0696b24b-t">Change of velocity on a bend</title><desc id="fg0696b24b-d">Velocities of 20 m s⁻¹ north and 20 m s⁻¹ east drawn from a common point, with Δv dashed.</desc><line x1="94.6" y1="205.4" x2="94.6" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="94.6,54.6 98.4,62.8 90.8,62.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="94.6" y="38.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 20 m s⁻¹</text><line x1="94.6" y1="205.4" x2="239.1" y2="205.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="245.4,205.4 237.2,209.2 237.2,201.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="259.4" y="209.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 20 m s⁻¹</text><line x1="94.6" y1="54.6" x2="240.9" y2="200.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="245.4,205.4 236.9,202.3 242.3,196.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="179.9" y="120.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="94.6" cy="205.4" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Velocities of 20 m s⁻¹ north and 20 m s⁻¹ east drawn from a common point, with Δv dashed.'),
('d50c23c6-f7b0-5d1a-82bd-7369cee9e209', 'ec015167-65fb-47df-b565-1055132ab4f3', '8ba3439e-0247-4a40-8f47-a5945e5c2968', 'a-level', '2.1', '9702 coursebook 2.1 · The meaning of acceleration', 49, 49, 'A skier''s speed rises from 4.0 m s⁻¹ to 16 m s⁻¹ down a slope in 6.0 s, then falls to 10 m s⁻¹ in 2.0 s on flat snow. (a) Calculate each acceleration. (b) Calculate the average acceleration over the 8.0 s.', NULL, 3, 'numeric'::answer_type, '0.75', 'm s⁻²', false, NULL, false, NULL, '(a) (16 − 4.0) ÷ 6.0 = 2.0 m s⁻²; (10 − 16) ÷ 2.0 = −3.0 m s⁻². (b) a = (10 − 4.0) ÷ 8.0 = 0.75 m s⁻². Mark scheme (5 marks). C1: slope. C1: flat. M1: overall Δv/t. C1: value. A1: a = 0.75 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fge94a6b10-t fge94a6b10-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge94a6b10-t">Skier</title><desc id="fge94a6b10-d">A v–t graph rising in a straight line from 4.0 m s⁻¹ to 16 m s⁻¹ in 6.0 s, then falling to 10 m s⁻¹ at 8.0 s.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="117.6" y1="34" x2="117.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205.7" y1="34" x2="205.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="293.9" y1="34" x2="293.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-