INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('844c27cf-90b9-5b65-9679-6968d48c8c87', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 1, 1, 'A motorbike accelerates from 5.0 m s⁻¹ to 25 m s⁻¹ in 4.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻²', false, NULL, false, NULL, 'a = (25 − 5.0) ÷ 4.0 = 5.0 m s⁻². Mark scheme (2 marks). C1: a = (v − u)/t. A1: a = 5.0 m s⁻².', 2, NULL, NULL),
('abd16ce9-e866-567a-a5dc-23c8c8e90ae2', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 2, 2, 'Which equation is used to calculate acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'a = (v − u) ÷ t', NULL, false, NULL, false, NULL, 'Change in velocity divided by time taken. Mark scheme (1 mark). B1: C (a = (v − u) ÷ t).', 1, NULL, NULL),
('d9eaf121-3550-536f-bb1c-3bc677662fb9', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 3, 3, 'A bowling ball goes from rest to 6.0 m s⁻¹ in 0.80 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '7.5', 'm s⁻²', false, NULL, false, NULL, 'a = 6.0 ÷ 0.80 = 7.5 m s⁻². Mark scheme (2 marks). C1: a = v/t from rest. A1: a = 7.5 m s⁻².', 2, NULL, NULL),
('89158c8f-08a0-5be0-b525-420b5c7d05dd', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 4, 4, 'A plane lands at 70 m s⁻¹ and stops in 28 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '-2.5', 'm s⁻²', false, NULL, true, NULL, 'a = (0 − 70) ÷ 28 = −2.5 m s⁻². Mark scheme (2 marks). C1: negative. A1: a = −2.5 m s⁻².', 2, NULL, NULL),
('c1421022-1014-5cff-a7cb-1957b8780965', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 5, 5, 'A falling stone''s speed increases from 4.9 m s⁻¹ to 14.7 m s⁻¹ in 1.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '9.8', 'm s⁻²', false, NULL, false, NULL, 'a = (14.7 − 4.9) ÷ 1.0 = 9.8 m s⁻². Mark scheme (2 marks). C1: Δv/t. A1: a = 9.8 m s⁻².', 2, NULL, NULL),
('f284913f-7301-5d94-88d7-88f243d133fe', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 6, 6, 'A car accelerates at 3.5 m s⁻² for 4.0 s from rest. Calculate its final speed.', NULL, 1, 'numeric'::answer_type, '14', 'm s⁻¹', false, NULL, false, NULL, 'v = 0 + 3.5 × 4.0 = 14 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 14 m s⁻¹.', 2, NULL, NULL),
('8eadd524-c310-5771-b7b3-4484a531d950', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 7, 7, 'In a = (v − u)/t, what does u represent?', NULL, 1, 'multiple_choice'::answer_type, 'The initial velocity', NULL, false, NULL, false, NULL, 'u is the velocity at the start of the interval. Mark scheme (1 mark). B1: A (The initial velocity).', 1, NULL, NULL),
('39bcc6cb-3dd8-555a-9512-5e6c463dd04b', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 8, 8, 'A trolley slows from 1.2 m s⁻¹ to 0.30 m s⁻¹ in 1.5 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '-0.6', 'm s⁻²', false, NULL, true, NULL, 'a = (0.30 − 1.2) ÷ 1.5 = −0.60 m s⁻². Mark scheme (2 marks). C1: Δv/t with sign. A1: a = −0.60 m s⁻².', 2, NULL, NULL),
('0a8fa392-3652-5073-965b-8aaa853c0b20', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 9, 9, 'A rocket reaches 300 m s⁻¹ from rest in 12 s. Calculate its average acceleration.', NULL, 1, 'numeric'::answer_type, '25', 'm s⁻²', false, NULL, false, NULL, 'a = 300 ÷ 12 = 25 m s⁻². Mark scheme (2 marks). C1: a = v/t. A1: a = 25 m s⁻².', 2, NULL, NULL),
('e2eb8d4d-7b71-58d3-a9d7-7fbdf8f73d09', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 10, 10, 'A van brakes at 4.0 m s⁻² from 20 m s⁻¹. Calculate the time to stop.', NULL, 1, 'numeric'::answer_type, '5', 's', false, NULL, false, NULL, 't = 20 ÷ 4.0 = 5.0 s. Mark scheme (2 marks). C1: t = Δv/a. A1: t = 5.0 s.', 2, NULL, NULL),
('f9082a5d-28aa-515e-a245-f497f8a3b246', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 11, 11, 'A skateboard goes from 2.0 m s⁻¹ to 5.0 m s⁻¹ in 2.0 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '1.5', 'm s⁻²', false, NULL, false, NULL, 'a = (5.0 − 2.0) ÷ 2.0 = 1.5 m s⁻². Mark scheme (1 mark). A1: a = 1.5 m s⁻².', 1, NULL, NULL),
('1997aa14-cd36-54fb-a34a-00ae268232c7', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 12, 12, 'What does a negative value of a = (v − u)/t show when the motion is in the positive direction?', NULL, 1, 'multiple_choice'::answer_type, 'The object is slowing down', NULL, false, NULL, false, NULL, 'v is less than u, so v − u is negative. Mark scheme (1 mark). B1: D (The object is slowing down).', 1, NULL, NULL),
('ab830a97-3b60-5e79-9864-1de6aee8e18e', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 13, 13, 'A swimmer pushes off a wall, reaching 2.4 m s⁻¹ from rest in 0.60 s. Calculate her acceleration.', NULL, 1, 'numeric'::answer_type, '4', 'm s⁻²', false, NULL, false, NULL, 'a = 2.4 ÷ 0.60 = 4.0 m s⁻². Mark scheme (2 marks). C1: a = v/t. A1: a = 4.0 m s⁻².', 2, NULL, NULL),
('df4455c0-b471-5471-803a-54328ba89928', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 14, 14, 'Starting at 5.0 m s⁻¹, a train gains speed at 0.25 m s⁻² for one minute (60 s). What speed does it reach?', NULL, 1, 'numeric'::answer_type, '20', 'm s⁻¹', false, NULL, false, NULL, 'v = 5.0 + 0.25 × 60 = 20 m s⁻¹. Mark scheme (2 marks). C1: v = u + at. A1: v = 20 m s⁻¹.', 2, NULL, NULL),
('ccdf0a3a-4d19-5978-bd05-48a6d761d8bc', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 15, 15, 'A golf ball leaves the club at 70 m s⁻¹ after 0.50 ms of contact, starting from rest. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '1.4e5', 'm s⁻²', false, NULL, false, NULL, 'a = 70 ÷ 0.50 × 10⁻³ = 140 000 m s⁻². Mark scheme (2 marks). C1: ms to s. A1: a = 1.4 × 10⁵ m s⁻².', 2, NULL, NULL),
('1dd47523-9f5e-509c-93e0-e6d8652aeb7e', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 16, 16, 'A car accelerates uniformly. Which pair of measurements is enough to calculate its acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'Its velocity at two times and the time between them', NULL, false, NULL, false, NULL, 'a = (v − u)/t needs u, v and t. Mark scheme (1 mark). B1: B (Its velocity at two times and the time between them).', 1, NULL, NULL),
('cbf7c5de-e4c3-5d1b-befa-783e895a1ea7', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 17, 17, 'A lift accelerates from rest to 2.0 m s⁻¹ in 1.6 s. Calculate its acceleration.', NULL, 1, 'numeric'::answer_type, '1.25', 'm s⁻²', false, NULL, false, NULL, 'a = 2.0 ÷ 1.6 = 1.25 m s⁻². Mark scheme (2 marks). C1: a = v/t. A1: a = 1.25 m s⁻².', 2, NULL, NULL),
('968272f3-57f7-5fe4-80c5-39c5174e95f5', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 18, 18, 'Flying off a fence, a pigeon goes from 3.0 m s⁻¹ to 12 m s⁻¹ in just 1.5 s. What is its acceleration?', NULL, 1, 'numeric'::answer_type, '6', 'm s⁻²', false, NULL, false, NULL, 'a = (12 − 3.0) ÷ 1.5 = 6.0 m s⁻². Mark scheme (2 marks). C1: Δv/t. A1: a = 6.0 m s⁻².', 2, NULL, NULL),
('7616f5da-cf1f-5048-9d07-95056e9ec199', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 19, 19, 'Friction on the ice reduces a puck''s velocity from 9.0 m s⁻¹ to 6.0 m s⁻¹ over 2.0 s. Find its acceleration.', NULL, 1, 'numeric'::answer_type, '-1.5', 'm s⁻²', false, NULL, true, NULL, 'a = (6.0 − 9.0) ÷ 2.0 = −1.5 m s⁻². Mark scheme (2 marks). C1: negative. A1: a = −1.5 m s⁻².', 2, NULL, NULL),
('6c90e4e0-43a5-5705-86d6-9e76bd70e9ce', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 20, 20, 'How long does a bus accelerating at 1.25 m s⁻² take to go from rest to 15 m s⁻¹?', NULL, 1, 'numeric'::answer_type, '12', 's', false, NULL, false, NULL, 't = 15 ÷ 1.25 = 12 s. Mark scheme (2 marks). C1: t = v/a. A1: t = 12 s.', 2, NULL, NULL),
('bebe41a6-d692-5c0f-bd5c-2b9b8c000ff2', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 21, 21, 'A car accelerates uniformly from 36 km h⁻¹ to 90 km h⁻¹ in 6.0 s. Calculate its acceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '2.5', 'm s⁻²', false, NULL, false, NULL, 'u = 36 ÷ 3.6 = 10 m s⁻¹; v = 90 ÷ 3.6 = 25 m s⁻¹; a = (25 − 10) ÷ 6.0 = 2.5 m s⁻². Mark scheme (3 marks). C1: convert speeds. C1: a. A1: a = 2.5 m s⁻².', 3, NULL, NULL),
('c2c5a2f6-cc6a-531e-918d-5ff790851ba0', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 22, 22, 'A ball rolling up a slope at 3.0 m s⁻¹ has an acceleration of −1.2 m s⁻². Calculate its velocity after 4.0 s.', NULL, 2, 'numeric'::answer_type, '-1.8', 'm s⁻¹', false, NULL, true, NULL, 'v = 3.0 + (−1.2) × 4.0 = −1.8 m s⁻¹ (rolling back down). Mark scheme (3 marks). C1: v = u + at. C1: sign. A1: v = −1.8 m s⁻¹.', 3, NULL, NULL),
('1bf5e1a2-dbb8-52a6-9798-a50dc6bc27f5', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 23, 23, 'In the slope problem above, what does the negative final velocity mean?', NULL, 2, 'multiple_choice'::answer_type, 'The ball has stopped and is now rolling back down the slope', NULL, false, NULL, false, NULL, 'The sign gives the direction. Mark scheme (3 marks). C1: reversed direction. C1: passed through zero. A1: C (The ball has stopped and is now rolling back down the slope).', 3, NULL, NULL),
