('6fb563a8-ecf2-5c16-aebc-fe5343fa340f', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 25, 25, 'A boat accelerates at 0.80 m s⁻² from 3.0 m s⁻¹. How long does it take to reach 15 m s⁻¹?', NULL, 2, 'numeric'::answer_type, '15', 's', false, NULL, false, NULL, 't = (15 − 3.0) ÷ 0.80 = 15 s. Mark scheme (3 marks). C1: rearranged. C1: value. A1: t = 15 s.', 3, NULL, NULL),
('faa10990-e4fe-5dad-a7cb-6ab992fb5b5e', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 26, 26, 'A ball is dropped onto a floor at 5.0 m s⁻¹ and rebounds at 4.0 m s⁻¹. The contact time is 0.012 s. Calculate the magnitude of its average acceleration.', NULL, 2, 'numeric'::answer_type, '750', 'm s⁻²', false, NULL, false, NULL, 'a = (4.0 + 5.0) ÷ 0.012 = 750 m s⁻². Mark scheme (3 marks). C1: Δv = 9.0 m s⁻¹. C1: ÷ t. A1: a = 750 m s⁻².', 3, NULL, NULL),
('8e4096a5-7188-5209-aff0-49c6e136efa7', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 27, 27, 'A student calculates a = (u − v)/t by mistake for a car speeding up. What will be wrong with her answer?', NULL, 2, 'multiple_choice'::answer_type, 'Its sign will be negative instead of positive', NULL, false, NULL, false, NULL, 'The magnitude is right but the direction is reversed. Mark scheme (3 marks). C1: magnitude correct. C1: sign wrong. A1: A (Its sign will be negative instead of positive).', 3, NULL, NULL),
('593f9ff5-328a-5195-b068-48efca940355', 'ec015167-65fb-47df-b565-1055132ab4f3', '91cb1c54-423a-4525-a723-99c1e9e9bf6b', 'a-level', '2.2', '9702 coursebook 2.2 · Calculating acceleration', 28, 28, 'A car accelerates uniformly. Its speed is 8.0 m s⁻¹ at t = 2.0 s and 20 m s⁻¹ at t = 6.0 s. Calculate its acceleration.', NULL, 2, 'numeric'::answer_type, '3', 'm s⁻²', false, NULL, false, NULL, 'a = (20 − 8.0) ÷ (6.0 − 2.0) = 3.0 m s⁻². Mark scheme (3 marks). C1: Δv. C1: Δt. A1: a = 3.0 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg2ff02b8c-t fg2ff02b8c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2ff02b8c-t">Uniform acceleration</title><desc id="fg2ff02b8c-d">A straight v–t line through (2.0 s, 8.0 m s⁻¹) and (6.0 s, 20 m s⁻¹).</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="79.8" y1="34" x2="79.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130.2" y1="34" x2="130.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="180.5" y1="34" x2="180.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230.9" y1="34" x2="230.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="281.3" y1="34" x2="281.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="331.6" y1="34" x2="331.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1