INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('416f73e2-957f-547a-9065-381daa19dc33', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 1, 1, 'What is the SI unit of acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'm s⁻²', NULL, false, NULL, false, NULL, 'Metres per second, per second. Mark scheme (1 mark). B1: C (m s⁻²).', 1, NULL, NULL),
('ce9a7fdf-3963-5922-b09c-6b336dfbcefc', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 2, 2, 'Why is acceleration measured in m s⁻²?', NULL, 1, 'multiple_choice'::answer_type, 'It is a change of velocity (m s⁻¹) per second (s)', NULL, false, NULL, false, NULL, '(m s⁻¹) ÷ s = m s⁻². Mark scheme (1 mark). B1: A (It is a change of velocity (m s⁻¹) per second (s)).', 1, NULL, NULL),
('83c2a7c6-04e6-51c7-bbf8-2d7137ecefdc', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 3, 3, 'Convert an acceleration of 3.6 km h⁻¹ per second into m s⁻².', NULL, 1, 'numeric'::answer_type, '1', 'm s⁻²', false, NULL, false, NULL, '3.6 km h⁻¹ = 3.6 ÷ 3.6 = 1.0 m s⁻¹, so a = 1.0 m s⁻². Mark scheme (2 marks). C1: km h⁻¹ to m s⁻¹. A1: a = 1.0 m s⁻².', 2, NULL, NULL),
('1a60f7e6-14b8-5095-b4d2-5b438eb8f6ef', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 4, 4, 'Which unit could NOT be a unit of acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'm s⁻¹', NULL, false, NULL, false, NULL, 'm s⁻¹ is a unit of velocity. Mark scheme (1 mark). B1: D (m s⁻¹).', 1, NULL, NULL),
('0163c3b5-ee9d-5cde-bf43-1d9a1e6e7b62', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 5, 5, 'Express 250 cm s⁻² in m s⁻².', NULL, 1, 'numeric'::answer_type, '2.5', 'm s⁻²', false, NULL, false, NULL, 'a = 250 ÷ 100 = 2.5 m s⁻². Mark scheme (2 marks). C1: cm to m. A1: a = 2.5 m s⁻².', 2, NULL, NULL),
('162fd8dd-0647-5983-ba69-eb19e27dcca4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 6, 6, 'Which is equivalent to 1 m s⁻²?', NULL, 1, 'multiple_choice'::answer_type, '1 N kg⁻¹', NULL, false, NULL, false, NULL, 'F = ma, so N kg⁻¹ = m s⁻². Mark scheme (1 mark). B1: B (1 N kg⁻¹).', 1, NULL, NULL),
('3ce9c821-d16a-523a-bf8e-2622bd45e76c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 7, 7, 'Express 9.81 m s⁻² in km h⁻¹ s⁻¹ (km h⁻¹ gained per second).', NULL, 1, 'numeric'::answer_type, '35.32', 'km h⁻¹ s⁻¹', false, NULL, false, NULL, '9.81 m s⁻¹ = 9.81 × 3.6 = 35.3 km h⁻¹, so 35.3 km h⁻¹ s⁻¹. Mark scheme (2 marks). C1: × 3.6. A1: a = 35.3 km h⁻¹ s⁻¹.', 2, NULL, NULL),
('d26e909e-3478-50df-994d-4cb43f68b3e1', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 8, 8, 'A car''s acceleration is given as "0 to 100 km h⁻¹ in 8 s". Which quantity is being described?', NULL, 1, 'multiple_choice'::answer_type, 'Average acceleration', NULL, false, NULL, false, NULL, 'A change of speed in a time. Mark scheme (1 mark). B1: C (Average acceleration).', 1, NULL, NULL),
('96ad5947-ea1a-5b20-9c5f-145c23dc6d7f', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 9, 9, 'A car goes from 0 to 100 km h⁻¹ in 8.0 s. Calculate its average acceleration in m s⁻².', NULL, 1, 'numeric'::answer_type, '3.472', 'm s⁻²', false, NULL, false, NULL, 'v = 100 ÷ 3.6 = 27.78 m s⁻¹; a = 27.78 ÷ 8.0 = 3.47 m s⁻². Mark scheme (2 marks). C1: convert then divide. A1: a = 3.47 m s⁻².', 2, NULL, NULL),
('601b2d7e-b7b8-5b48-bbd6-36699abb249d', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 10, 10, 'Which SI base units make up the unit of acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'm and s', NULL, false, NULL, false, NULL, 'The unit m s⁻² uses only metres and seconds. Mark scheme (1 mark). B1: A (m and s).', 1, NULL, NULL),
('409efcb5-d9c3-5ed9-9413-e999e9eb3f36', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 11, 11, 'Express an acceleration of 0.050 m s⁻² in mm s⁻².', NULL, 1, 'numeric'::answer_type, '50', 'mm s⁻²', false, NULL, false, NULL, 'a = 0.050 × 1000 = 50 mm s⁻². Mark scheme (2 marks). C1: m to mm. A1: a = 50 mm s⁻².', 2, NULL, NULL),
('9c83f3f3-1e18-5158-a7df-e9d28574f013', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 12, 12, 'A student writes the acceleration of a car as "3 m/s". What is wrong?', NULL, 1, 'multiple_choice'::answer_type, 'The unit is that of velocity, not acceleration; it should be m s⁻²', NULL, false, NULL, false, NULL, 'Acceleration needs per second squared. Mark scheme (1 mark). B1: D (The unit is that of velocity, not acceleration; it should be m s⁻²).', 1, NULL, NULL),
('0a92138a-5112-5ab6-afea-20e718e744eb', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 13, 13, 'Convert 2.0 km h⁻¹ s⁻¹ to m s⁻².', NULL, 1, 'numeric'::answer_type, '0.5556', 'm s⁻²', false, NULL, false, NULL, 'a = 2.0 ÷ 3.6 = 0.556 m s⁻². Mark scheme (1 mark). A1: a = 0.556 m s⁻².', 1, NULL, NULL),
('9987a546-b2ab-57b7-87e0-aaa6d2612b7e', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 14, 14, 'In what unit is the gravitational field strength g usually quoted, and is it equivalent to m s⁻²?', NULL, 1, 'multiple_choice'::answer_type, 'N kg⁻¹, which is equivalent to m s⁻²', NULL, false, NULL, false, NULL, 'g is both a field strength and an acceleration. Mark scheme (1 mark). B1: B (N kg⁻¹, which is equivalent to m s⁻²).', 1, NULL, NULL),
('f30f939c-81df-5cf3-9700-7106a8587423', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 15, 15, 'An acceleration is 1.8 × 10³ cm s⁻². Express it in m s⁻².', NULL, 1, 'numeric'::answer_type, '18', 'm s⁻²', false, NULL, false, NULL, 'a = 1.8 × 10³ ÷ 100 = 18 m s⁻². Mark scheme (2 marks). C1: ÷ 100. A1: a = 18 m s⁻².', 2, NULL, NULL),
('8996ae5d-1608-5bc7-9fcf-c114a84dce88', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 16, 16, 'Which expression has the units of acceleration?', NULL, 1, 'multiple_choice'::answer_type, 'velocity² ÷ distance', NULL, false, NULL, false, NULL, '(m² s⁻²) ÷ m = m s⁻². Mark scheme (1 mark). B1: C (velocity² ÷ distance).', 1, NULL, NULL),
('249b20f0-679d-5eb4-89bd-6ce504f08c75', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 17, 17, 'A train''s speed changes by 54 km h⁻¹ in 30 s. Calculate its acceleration in m s⁻².', NULL, 1, 'numeric'::answer_type, '0.5', 'm s⁻²', false, NULL, false, NULL, 'Δv = 54 ÷ 3.6 = 15 m s⁻¹; a = 15 ÷ 30 = 0.50 m s⁻². Mark scheme (2 marks). C1: convert Δv. A1: a = 0.50 m s⁻².', 2, NULL, NULL),
('9ee6d2a5-6461-5209-a393-13bf87afa5f0', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 18, 18, 'A cyclist''s speed rises by 0.72 km h⁻¹ every second (0.72 km h⁻¹ s⁻¹). What is her acceleration in m s⁻²?', NULL, 1, 'numeric'::answer_type, '0.2', 'm s⁻²', false, NULL, false, NULL, 'a = 0.72 ÷ 3.6 = 0.20 m s⁻². Mark scheme (2 marks). C1: ÷ 3.6. A1: a = 0.20 m s⁻².', 2, NULL, NULL),
('074d6b4e-2a76-5863-a0e9-ed344afc1157', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 19, 19, 'Which is the largest acceleration: 1 m s⁻², 100 cm s⁻², 3.6 km h⁻¹ s⁻¹ or 2 N kg⁻¹?', NULL, 1, 'multiple_choice'::answer_type, '2 N kg⁻¹', NULL, false, NULL, false, NULL, 'The first three all equal 1 m s⁻²; 2 N kg⁻¹ is 2 m s⁻². Mark scheme (1 mark). B1: D (2 N kg⁻¹).', 1, NULL, NULL),
('736f935d-d733-55f3-b523-3bec1af99019', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 20, 20, 'A slow conveyor belt speeds up at 45 mm s⁻². Write this acceleration in m s⁻².', NULL, 1, 'numeric'::answer_type, '0.045', 'm s⁻²', false, NULL, false, NULL, 'a = 45 ÷ 1000 = 0.045 m s⁻². Mark scheme (2 marks). C1: mm to m. A1: a = 0.045 m s⁻².', 2, NULL, NULL),
('7c07800e-5c8c-54a5-9003-0a056ef1ce53', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 21, 21, 'Show which expression is homogeneous with acceleration: (A) F/m (B) v/s (C) s/t', NULL, 2, 'multiple_choice'::answer_type, 'F/m only', NULL, false, NULL, false, NULL, 'F/m: N kg⁻¹ = m s⁻². v/s has unit s⁻¹; s/t is m s⁻¹. Mark scheme (3 marks). C1: F/m correct. C1: others checked. A1: A (F/m only).', 3, NULL, NULL),
('1963bfd3-dec4-5bb3-8811-6cfd5996ea49', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 22, 22, 'A car decelerates from 108 km h⁻¹ to rest in 6.0 s. Calculate the magnitude of its deceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '5', 'm s⁻²', false, NULL, false, NULL, 'u = 108 ÷ 3.6 = 30 m s⁻¹; a = 30 ÷ 6.0 = 5.0 m s⁻². Mark scheme (3 marks). C1: convert. C1: a. A1: a = 5.0 m s⁻².', 3, NULL, NULL),
('f1ce5891-f7f0-5eef-8d03-be727f1b5a87', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 23, 23, 'An aircraft catapult takes a jet from rest to 270 km h⁻¹ in 2.5 s. Calculate the acceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '30', 'm s⁻²', false, NULL, false, NULL, 'v = 270 ÷ 3.6 = 75 m s⁻¹; a = 75 ÷ 2.5 = 30 m s⁻². Mark scheme (3 marks). C1: convert. C1: a. A1: a = 30 m s⁻².', 3, NULL, NULL),
('96a18a01-9a6e-5485-a3dd-3197f955c592', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 24, 24, 'Express the catapult acceleration of 30 m s⁻² as a multiple of g (g = 9.81 m s⁻²).', NULL, 2, 'numeric'::answer_type, '3.058', NULL, false, NULL, false, NULL, '30 ÷ 9.81 = 3.06, so about 3.1g. Mark scheme (3 marks). C1: ÷ g. C1: value. A1: a/g = 3.06.', 3, NULL, NULL),
('3451134b-d0ac-5357-adc6-a33af09c88d4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 25, 25, 'Why can an acceleration be given in "g"?', NULL, 2, 'multiple_choice'::answer_type, 'It compares the acceleration with that of free fall, 9.81 m s⁻²', NULL, false, NULL, false, NULL, 'For example, pilots experience several g. Mark scheme (3 marks). C1: ratio. C1: to 9.81 m s⁻². A1: D (It compares the acceleration with that of free fall, 9.81 m s⁻²).', 3, NULL, NULL),
('4051f00b-4bc8-54b7-833b-2a8423196f29', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 26, 26, 'A pilot experiences 6.0g. Calculate this acceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '58.86', 'm s⁻²', false, NULL, false, NULL, 'a = 6.0 × 9.81 = 58.9 m s⁻². Mark scheme (3 marks). C1: × 9.81. C1: value. A1: a = 58.9 m s⁻².', 3, NULL, NULL),
('68e10d8d-db73-5804-b9e4-c1c022334fc4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 27, 27, 'A snail''s speed increases by 1.2 mm s⁻¹ in 4.0 s. Calculate its acceleration in m s⁻², in units of 10⁻⁴ m s⁻².', NULL, 2, 'numeric'::answer_type, '3', '10⁻⁴ m s⁻²', false, NULL, false, NULL, 'a = 1.2 × 10⁻³ ÷ 4.0 = 3.0 × 10⁻⁴ m s⁻². Mark scheme (3 marks). C1: mm to m. C1: ÷ t. A1: a = 3.0 × 10⁻⁴ m s⁻².', 3, NULL, NULL),
('faa22d8e-5a69-5767-b712-23048906f7b7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 28, 28, 'A quantity is calculated as (velocity change) ÷ (time) × (time) ÷ (distance). What are its units?', NULL, 2, 'multiple_choice'::answer_type, 's⁻¹', NULL, false, NULL, false, NULL, '(m s⁻¹ ÷ s) × s ÷ m = s⁻¹. Mark scheme (3 marks). C1: combine. C1: simplify. A1: B (s⁻¹).', 3, NULL, NULL),
('71bca6a9-63e8-5536-b717-72b40761a222', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 29, 29, 'In v² = u² + 2as, show that the units are consistent by finding the unit of 2as when a is in m s⁻² and s in m. Then calculate 2as for a = 3.0 m s⁻² and s = 24 m, in m² s⁻².', NULL, 2, 'numeric'::answer_type, '144', 'm² s⁻²', false, NULL, false, NULL, '2as has units m s⁻² × m = m² s⁻², the same as v². 2as = 2 × 3.0 × 24 = 144 m² s⁻². Mark scheme (3 marks). C1: units. C1: value. A1: 2as = 144 m² s⁻².', 3, NULL, NULL),
('82d3b230-3794-5f80-b839-88e939676786', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 30, 30, 'A Formula 1 car brakes from 300 km h⁻¹ to 80 km h⁻¹ in 2.0 s. Calculate its deceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '30.56', 'm s⁻²', false, NULL, false, NULL, 'Δv = (300 − 80) ÷ 3.6 = 61.11 m s⁻¹; a = 61.11 ÷ 2.0 = 30.6 m s⁻². Mark scheme (3 marks). C1: Δv in m s⁻¹. C1: a. A1: a = 30.6 m s⁻².', 3, NULL, NULL),
('9980621e-3085-5581-8142-c417a98ab5f8', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 31, 31, 'Express the Formula 1 braking deceleration of 30.6 m s⁻² in units of g (g = 9.81 m s⁻²).', NULL, 2, 'numeric'::answer_type, '3.119', NULL, false, NULL, false, NULL, 'In units of g: 30.6 ÷ 9.81 = 3.12. Mark scheme (3 marks). C1: ÷ g. C1: value. A1: a/g = 3.12.', 3, NULL, NULL),
('19519e1d-9c8a-5c2b-8605-bc766b11e497', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 32, 32, 'A student says the unit of acceleration is "m per s per s". Is this right?', NULL, 2, 'multiple_choice'::answer_type, 'Yes, m s⁻¹ s⁻¹ = m s⁻²', NULL, false, NULL, false, NULL, 'Velocity per unit time. Mark scheme (3 marks). C1: equivalent. C1: reason. A1: C (Yes, m s⁻¹ s⁻¹ = m s⁻²).', 3, NULL, NULL),
('564bca37-ea88-5c0c-bc3e-89ad261c6d98', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 33, 33, 'A car manual gives a deceleration of 0.80g for emergency braking. Calculate the time to stop from 31 m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.95', 's', false, NULL, false, NULL, 'a = 0.80 × 9.81 = 7.848 m s⁻²; t = 31 ÷ 7.848 = 3.95 s. Mark scheme (3 marks). C1: a in m s⁻². C1: t. A1: t = 3.95 s.', 3, NULL, NULL),
('7e894589-72ed-5584-b21e-0b1fcb67cdb6', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 34, 34, 'A space probe''s ion engine produces an acceleration of 9.0 × 10⁻⁵ m s⁻². How long does it take to gain 1.0 km s⁻¹, in days?', NULL, 2, 'numeric'::answer_type, '128.6', 'days', false, NULL, false, NULL, 't = 1000 ÷ 9.0 × 10⁻⁵ = 1.111 × 10⁷ s. In days: 1.111 × 10⁷ ÷ 86 400 = 129. Mark scheme (4 marks). C1: km s⁻¹ to m s⁻¹. C1: time in s. C1: days. A1: t = 129 days.', 4, NULL, NULL),
('e5db0446-54ad-5bc0-b011-7e305e4f73b0', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 35, 35, 'Which of these is a correct way to state the free-fall acceleration on the Moon?', NULL, 2, 'multiple_choice'::answer_type, '1.6 m s⁻²', NULL, false, NULL, false, NULL, 'An acceleration needs m s⁻² (or N kg⁻¹). Mark scheme (3 marks). C1: m s⁻². C1: others wrong. A1: A (1.6 m s⁻²).', 3, NULL, NULL),
('99c0d9ca-282f-5be8-9860-2371572f8bc9', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 36, 36, 'An acceleration of 4.0 m s⁻² acts for 1 minute from rest. Calculate the speed reached, in km h⁻¹.', NULL, 2, 'numeric'::answer_type, '864', 'km h⁻¹', false, NULL, false, NULL, 'v = 4.0 × 60 = 240 m s⁻¹. In km h⁻¹: 240 × 3.6 = 864. Mark scheme (3 marks). C1: v = at. C1: × 3.6. A1: v = 864 km h⁻¹.', 3, NULL, NULL),
('6d9d2352-d771-5c7d-a6fb-85911c0a912b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 37, 37, 'An acceleration is 7.2 km h⁻¹ per minute. Express it in m s⁻², in units of 10⁻² m s⁻².', NULL, 2, 'numeric'::answer_type, '3.333', '10⁻² m s⁻²', false, NULL, false, NULL, '7.2 km h⁻¹ = 2.0 m s⁻¹; a = 2.0 ÷ 60 = 0.0333 m s⁻². Mark scheme (3 marks). C1: convert speed. C1: per minute to per second. A1: a = 3.33 × 10⁻² m s⁻².', 3, NULL, NULL),
('0f1a4b34-a66c-5621-a5c5-a34b1edbf0ed', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 38, 38, 'A sports car is advertised as reaching 60 km h⁻¹ from rest in 3.0 s. Calculate its average acceleration in m s⁻².', NULL, 2, 'numeric'::answer_type, '5.556', 'm s⁻²', false, NULL, false, NULL, 'v = 60 ÷ 3.6 = 16.67 m s⁻¹; a = 16.67 ÷ 3.0 = 5.56 m s⁻². Mark scheme (3 marks). C1: convert. C1: a. A1: a = 5.56 m s⁻².', 3, NULL, NULL),
('46283f7a-c46d-5475-b063-167ee45a3bfd', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 39, 39, 'The free-fall acceleration on the Moon is 1.6 m s⁻². Express it as a fraction of 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.1631', NULL, false, NULL, false, NULL, 'Fraction = 1.6 ÷ 9.81 = 0.163. Mark scheme (3 marks). C1: ratio. C1: value. A1: fraction = 0.163.', 3, NULL, NULL),
('beb163a1-1156-53ba-9b62-349d8d4ccf68', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 40, 40, 'A roller coaster gives riders an acceleration of 3.5g. Express this in m s⁻².', NULL, 2, 'numeric'::answer_type, '34.34', 'm s⁻²', false, NULL, false, NULL, 'a = 3.5 × 9.81 = 34.3 m s⁻². Mark scheme (3 marks). C1: × g. C1: value. A1: a = 34.3 m s⁻².', 3, NULL, NULL),
('ec5fbb5c-997e-5058-ba28-3acf85cfdc7c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 41, 41, 'Which value equals 1 cm s⁻²?', NULL, 2, 'multiple_choice'::answer_type, '0.01 m s⁻²', NULL, false, NULL, false, NULL, '1 cm = 0.01 m, so 1 cm s⁻² = 0.01 m s⁻². Mark scheme (3 marks). C1: cm to m. C1: value. A1: B (0.01 m s⁻²).', 3, NULL, NULL),
('ca3e6c97-e10b-5675-864a-87e4b44158cb', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 42, 42, 'A car accelerates from 0 to 60 miles per hour in 7.5 s (1 mile = 1609 m). (a) Convert 60 miles per hour to m s⁻¹. (b) Calculate the average acceleration in m s⁻².', NULL, 3, 'numeric'::answer_type, '3.576', 'm s⁻²', false, NULL, false, NULL, '(a) v = 60 × 1609 ÷ 3600 = 26.82 m s⁻¹. (b) a = 26.82 ÷ 7.5 = 3.58 m s⁻². Mark scheme (5 marks). C1: miles to m. C1: h to s. M1: a = v/t. C1: value. A1: a = 3.58 m s⁻².', 5, NULL, NULL),
('9f1af625-c561-5ccc-90b7-a2cf5dac566c', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 43, 43, 'An astronaut must not exceed 4.0g. A rocket reaches 7.8 km s⁻¹ from rest. (a) Calculate the maximum acceleration in m s⁻². (b) Calculate the minimum time to reach 7.8 km s⁻¹. (c) Give the answer to (b) in minutes.', NULL, 3, 'numeric'::answer_type, '3.313', 'min', false, NULL, false, NULL, '(a) a = 4.0 × 9.81 = 39.2 m s⁻². (b) t = 7800 ÷ 39.24 = 198.8 s. (c) 198.8 ÷ 60 = 3.31 min. Mark scheme (6 marks). C1: a. C1: km s⁻¹ to m s⁻¹. M1: t = v/a. C1: seconds. C1: minutes. A1: t = 3.31 min.', 6, NULL, NULL),
('8554d770-3a82-58ea-83ab-9202ef1e31f4', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 44, 44, 'Show that F/m has the units of acceleration, given that 1 N = 1 kg m s⁻². Then calculate the acceleration of a 1500 kg car pushed by a resultant force of 2700 N.', NULL, 3, 'numeric'::answer_type, '1.8', 'm s⁻²', false, NULL, false, NULL, 'Units: kg m s⁻² ÷ kg = m s⁻². a = 2700 ÷ 1500 = 1.8 m s⁻². Mark scheme (5 marks). M1: base units of N. B1: cancels to m s⁻². M1: a = F/m. C1: value. A1: a = 1.8 m s⁻².', 5, NULL, NULL),
('7bbf7d79-ba92-5f02-8a89-5c8601279cd7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 45, 45, 'A cyclist''s speed rises from 18 km h⁻¹ to 36 km h⁻¹ in 0.25 minutes. (a) Convert the speeds to m s⁻¹. (b) Convert the time to s. (c) Calculate the acceleration in m s⁻².', NULL, 3, 'numeric'::answer_type, '0.3333', 'm s⁻²', false, NULL, false, NULL, '(a) 5.0 m s⁻¹ and 10 m s⁻¹. (b) 0.25 × 60 = 15 s. (c) a = (10 − 5.0) ÷ 15 = 0.333 m s⁻². Mark scheme (6 marks). C1: speeds. C1: time. M1: a = Δv/t. C1: substitution. C1: value. A1: a = 0.333 m s⁻².', 6, NULL, NULL),
('cd982151-5c72-56e0-bc77-af4385a5a306', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 46, 46, 'Light-gate data give a speed of 42 cm s⁻¹ and, 0.60 s later, 78 cm s⁻¹. (a) Calculate the acceleration in cm s⁻². (b) Express it in m s⁻².', NULL, 3, 'numeric'::answer_type, '0.6', 'm s⁻²', false, NULL, false, NULL, '(a) a = (78 − 42) ÷ 0.60 = 60 cm s⁻². (b) 60 ÷ 100 = 0.60 m s⁻². Mark scheme (5 marks). C1: Δv. C1: a in cm s⁻². M1: ÷ 100. C1: value. A1: a = 0.60 m s⁻².', 5, NULL, NULL),
('4b99688f-127e-5e3e-89e1-0f4a153ddc3b', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 47, 47, 'Using base units, show that √(2as) has the same units as velocity, and calculate √(2as) for a = 2.5 m s⁻² and s = 45 m.', NULL, 3, 'numeric'::answer_type, '15', 'm s⁻¹', false, NULL, false, NULL, 'Units: √(m s⁻² × m) = √(m² s⁻²) = m s⁻¹. √(2 × 2.5 × 45) = 15.0 m s⁻¹. Mark scheme (5 marks). M1: multiply units. B1: square root gives m s⁻¹. C1: substitution. C1: value. A1: v = 15 m s⁻¹.', 5, NULL, NULL),
('d2e8f5d3-ae06-5438-a314-92c05d1fe459', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 48, 48, 'A cheetah reaches 100 km h⁻¹ from rest in 3.0 s. A car reaches 100 km h⁻¹ in 4.5 s. (a) Convert 100 km h⁻¹ to m s⁻¹. (b) Calculate both accelerations. (c) Calculate the ratio cheetah ÷ car.', NULL, 3, 'numeric'::answer_type, '1.5', NULL, false, NULL, false, NULL, '(a) 27.78 m s⁻¹. (b) 9.26 m s⁻² and 6.17 m s⁻². (c) Ratio = 4.5 ÷ 3.0 = 1.5. Mark scheme (6 marks). C1: conversion. C1: cheetah. C1: car. M1: ratio. C1: value. A1: ratio = 1.5.', 6, NULL, NULL),
('940f2a07-ac2c-5993-8357-ff95b7d1d3b7', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 49, 49, 'Constant acceleration a for time t from rest gives speed v = at. (a) Show the units of at are m s⁻¹. (b) Find the time for a = 0.15 m s⁻² to give 54 km h⁻¹.', NULL, 3, 'numeric'::answer_type, '100', 's', false, NULL, false, NULL, '(a) m s⁻² × s = m s⁻¹. (b) 54 km h⁻¹ = 15 m s⁻¹; t = 15 ÷ 0.15 = 100 s. Mark scheme (5 marks). B1: units. C1: convert speed. M1: t = v/a. C1: value. A1: t = 100 s.', 5, NULL, NULL),
('af496a96-e810-562a-8800-22d23d23fd52', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 50, 50, 'A falling object''s speed increases by 32 ft s⁻¹ every second, where 1 ft = 0.305 m. (a) Express the acceleration in m s⁻². (b) Calculate the percentage difference from 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.5097', '%', false, NULL, false, NULL, '(a) a = 32 × 0.305 = 9.76 m s⁻². (b) % = (9.81 − 9.76) ÷ 9.81 × 100 = 0.51 %. Mark scheme (5 marks). C1: ft to m. C1: value. M1: % difference. C1: value. A1: % difference = 0.51%.', 5, NULL, NULL),
('15875edd-58ea-5ab8-93db-89c630c89bf3', 'ec015167-65fb-47df-b565-1055132ab4f3', 'cfa4c849-4465-4806-9a6e-29163a3db134', 'a-level', '2.3', '9702 coursebook 2.3 · Units of acceleration', 51, 51, 'A car accelerates at 2.5 m s⁻² for 12 s from rest. (a) Calculate its final speed in m s⁻¹. (b) Express this speed in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '108', 'km h⁻¹', false, NULL, false, NULL, '(a) v = 2.5 × 12 = 30 m s⁻¹. (b) 30 × 3.6 = 108 km h⁻¹. Mark scheme (5 marks). M1: v = at. C1: 30 m s⁻¹. M1: × 3.6. C1: value. A1: v = 108 km h⁻¹.', 5, NULL, NULL)
